#!/usr/bin/env node
/**
 * Builds conformance/vectors.json and vectors.lock.json from fixed inputs.
 *
 * External anchors are asserted here, so the vectors can only be regenerated by an
 * implementation that agrees with the published standards:
 *   - RFC 8785 section 3.2 canonicalization sample
 *   - RFC 8032 section 7.1 Ed25519 test vectors 1 and 2
 *   - the base58btc "Hello World!" vector
 *   - the did:key specification's Ed25519 example identifier (framing round-trip)
 *
 * Vectors are immutable per vectors_version. Changing any input here requires a new
 * vectors_version and a new lock.
 */

import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import {
  base58Decode,
  base58Encode,
  canonicalJson,
  createEnvelope,
  createReceiptRecord,
  didFromPublicKeyBytes,
  hashPayload,
  hashRecord,
  keyPairFromSeed,
  publicKeyBytesFromDid,
  sha256Hex,
  signBytes
} from '../src/index.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const VECTORS_VERSION = '2';

function assert(condition, message) {
  if (!condition) throw new Error(`conformance anchor failed: ${message}`);
}

// RFC 8785, section 3.2.2 input and 3.2.3 output.
const rfc8785Input = {
  numbers: [333333333.33333329, 1e30, 4.5, 2e-3, 0.000000000000000000000000001],
  string: '€$\u000f\nA\'B"\\\\"/',
  literals: [null, true, false]
};
const rfc8785Expected = '{"literals":[null,true,false],"numbers":[333333333.3333333,1e+30,4.5,0.002,1e-27],"string":"€$\\u000f\\nA\'B\\"\\\\\\\\\\"/"}';
assert(canonicalJson(rfc8785Input) === rfc8785Expected, 'RFC 8785 sample');

// RFC 8032, section 7.1.
const rfc8032 = [
  {
    id: 'rfc8032-test-1',
    seed_hex: '9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60',
    public_key_hex: 'd75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a',
    message_hex: '',
    expected_signature_hex:
      'e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b'
  },
  {
    id: 'rfc8032-test-2',
    seed_hex: '4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb',
    public_key_hex: '3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c',
    message_hex: '72',
    expected_signature_hex:
      '92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00'
  }
];
for (const vector of rfc8032) {
  const pair = keyPairFromSeed(vector.seed_hex);
  assert(pair.public_key_hex === vector.public_key_hex, `${vector.id} public key`);
  const signature = signBytes(Buffer.from(vector.message_hex, 'hex'), pair);
  assert(signature.toString('hex') === vector.expected_signature_hex, `${vector.id} signature`);
}

// base58btc.
assert(base58Encode(Buffer.from('Hello World!', 'utf8')) === '2NEpo7TZRRrLZSi2U', 'base58 Hello World!');
assert(base58Decode('2NEpo7TZRRrLZSi2U').toString('utf8') === 'Hello World!', 'base58 decode');
assert(base58Encode(Buffer.from([0, 0, 1])) === '112', 'base58 leading zeros');

// did:key specification Ed25519 example: must decode to 34 bytes with the ed25519-pub
// multicodec prefix and re-encode to the same identifier.
const specDid = 'did:key:z6MkhaXgBZDvotDkL5257faiztiGiC2QtKLGpbnnEGta2doK';
const specKey = publicKeyBytesFromDid(specDid);
assert(specKey.length === 32, 'did:key example decodes to 32-byte key');
assert(didFromPublicKeyBytes(specKey) === specDid, 'did:key example round-trips');

// Canonical JSON. Inputs are stored as plain JSON (insertion order preserved), so a
// naive serializer that does not sort keys fails these.
const canonicalCases = [
  { id: 'rfc8785-sample', description: 'RFC 8785 section 3.2 sample', input: rfc8785Input },
  { id: 'empty-object', description: 'empty object', input: {} },
  { id: 'empty-array', description: 'empty array', input: [] },
  { id: 'nested-sorting', description: 'keys sorted at every depth', input: { b: { z: 1, a: [3, { y: 2, x: 1 }] }, a: 'x' } },
  { id: 'unicode-key-order', description: 'UTF-16 code unit ordering of keys', input: { 'é': 1, e: 2, 'A': 3, '😀': 4, 'Ａ': 5 } },
  { id: 'empty-string-key', description: 'empty string sorts first', input: { b: 1, '': 2, a: 3 } },
  { id: 'numbers', description: 'ECMAScript number formatting', input: { a: 1.0, b: 1e21, c: 1e-7, e: 0.1, f: 123456789012345680000, g: 5e-324, h: 100, i: 1e-6, j: -1.5e-9 } },
  { id: 'large-integers', description: 'integers above 2^53 are doubles in JSON', input: { a: 9007199254740993, b: 1000000000000000000000, c: 123456789012345678901234567890 } },
  { id: 'escapes', description: 'control characters and quotes', input: { s: '\u0000\u0001\u001f"\\/\b\f\n\r\t' } },
  { id: 'non-ascii-unescaped', description: 'non-ASCII and slash are not escaped', input: { s: 'héllo/wörld 😀' } },
  { id: 'nulls-and-booleans', description: 'literals inside arrays and objects', input: { a: [null, true, false, 0, ''], b: null } }
];

const canonical_json = canonicalCases.map((c) => ({
  id: c.id,
  description: c.description,
  input: JSON.parse(JSON.stringify(c.input)),
  expected_canonical: canonicalJson(c.input),
  expected_hash: hashPayload(c.input)
}));

// Hash references always cover canonical JSON, so a string payload is hashed quoted.
const hashCases = [
  { id: 'string-payload-is-quoted', input: 'hello' },
  { id: 'string-that-looks-like-json', input: '{"a":1}' },
  { id: 'object-payload', input: { a: 1 } },
  { id: 'number-payload', input: 42 },
  { id: 'null-payload', input: null },
  { id: 'array-payload', input: [1, 'two', { three: 3 }] }
];
const hash_payload = hashCases.map((c) => ({ id: c.id, input: c.input, expected_hash: hashPayload(c.input) }));
assert(hash_payload[0].expected_hash !== `sha256:${sha256Hex('hello')}`, 'string payloads must not hash as raw text');
assert(hash_payload[1].expected_hash !== hash_payload[2].expected_hash, 'string and object must differ');

const base58btc = [
  { id: 'hello-world', input_hex: Buffer.from('Hello World!', 'utf8').toString('hex'), expected: '2NEpo7TZRRrLZSi2U' },
  { id: 'leading-zeros', input_hex: '000001', expected: '112' },
  { id: 'single-zero', input_hex: '00', expected: '1' },
  { id: 'all-ff', input_hex: 'ffffffff', expected: base58Encode(Buffer.from('ffffffff', 'hex')) },
  { id: 'multicodec-ed25519', input_hex: 'ed01' + rfc8032[0].public_key_hex, expected: base58Encode(Buffer.from('ed01' + rfc8032[0].public_key_hex, 'hex')) }
];

const did_key = [
  { public_key_hex: rfc8032[0].public_key_hex, expected_did: didFromPublicKeyBytes(rfc8032[0].public_key_hex) },
  { public_key_hex: rfc8032[1].public_key_hex, expected_did: didFromPublicKeyBytes(rfc8032[1].public_key_hex) },
  { public_key_hex: specKey.toString('hex'), expected_did: specDid, source: 'did:key specification Ed25519 example' }
];

const ed25519 = rfc8032.map((v) => ({ ...v, source: 'RFC 8032 section 7.1' }));

const signerSeed = rfc8032[0].seed_hex;
const signer = keyPairFromSeed(signerSeed);
const otherSeed = rfc8032[1].seed_hex;

const ommPayload = {
  OBJECT_NAME: 'ISS (ZARYA)',
  OBJECT_ID: '1998-067A',
  EPOCH: '2026-01-01T00:00:00.000000',
  MEAN_MOTION: 15.5,
  ECCENTRICITY: 0.0005,
  INCLINATION: 51.64,
  RA_OF_ASC_NODE: 10.0,
  ARG_OF_PERICENTER: 20.0,
  MEAN_ANOMALY: 30.0,
  EPHEMERIS_TYPE: 0,
  CLASSIFICATION_TYPE: 'U',
  NORAD_CAT_ID: 25544,
  ELEMENT_SET_NO: 999,
  REV_AT_EPOCH: 1,
  BSTAR: 0.0001,
  MEAN_MOTION_DOT: 0.00001,
  MEAN_MOTION_DDOT: 0
};

const envelopeFirst = createEnvelope({ payload: ommPayload, payload_type: 'ccsds.omm.json/1', signer, created_at: '2026-01-01T00:00:00.000Z' });
const envelopeChained = createEnvelope({
  payload: { hello: 'world', n: [1, 2, 3] },
  payload_type: 'opaque.json/1',
  signer,
  created_at: '2026-01-01T00:00:01.000Z',
  previous_envelope_hash: envelopeFirst.envelope_hash
});
const envelopeDetached = createEnvelope({ payload: 'a bare string payload', payload_type: 'opaque.json/1', signer, created_at: '2026-01-01T00:00:02.000Z', detached: true });

const envelopeCases = [
  { id: 'envelope-omm', env: envelopeFirst, payload: ommPayload, payload_type: 'ccsds.omm.json/1', created_at: '2026-01-01T00:00:00.000Z', previous_envelope_hash: null },
  { id: 'envelope-chained', env: envelopeChained, payload: { hello: 'world', n: [1, 2, 3] }, payload_type: 'opaque.json/1', created_at: '2026-01-01T00:00:01.000Z', previous_envelope_hash: envelopeFirst.envelope_hash },
  { id: 'envelope-detached-string', env: envelopeDetached, payload: 'a bare string payload', payload_type: 'opaque.json/1', created_at: '2026-01-01T00:00:02.000Z', previous_envelope_hash: null, detached: true }
];
const envelope = envelopeCases.map((c) => ({
  id: c.id,
  signer_seed_hex: signerSeed,
  payload_type: c.payload_type,
  created_at: c.created_at,
  previous_envelope_hash: c.previous_envelope_hash,
  ...(c.detached ? { detached: true } : {}),
  payload: c.payload,
  expected: {
    signer: c.env.signer,
    payload_hash: c.env.payload_hash,
    envelope_hash: c.env.envelope_hash,
    envelope_id: c.env.envelope_id,
    signature_value: c.env.signature.value
  }
}));

const receiptRecord = { record_type: 'entity', entity_id: 'NODE-1', entity_type: 'node', created_at: '2026-01-01T00:00:00Z' };
const first = createReceiptRecord({ record: receiptRecord, issuer: signer, timestamp: '2026-01-01T00:00:02.000Z' });
const second = createReceiptRecord({
  record: { ...receiptRecord, status: 'active' },
  previous_hash: first.receipt_hash,
  issuer: signer,
  timestamp: '2026-01-01T00:00:03.000Z'
});
const unsigned = createReceiptRecord({ record: receiptRecord, issuer: 'iricity-state-stack', timestamp: '2026-01-01T00:00:04.000Z' });
const legacyCore = { record_hash: hashRecord(receiptRecord), previous_hash: null, timestamp: '2026-01-01T00:00:05.000Z', issuer: 'legacy-registry' };
const legacy = {
  record_type: 'receipt',
  receipt_id: `rcp_${legacyCore.record_hash.slice(7, 23)}`,
  ...legacyCore,
  signature: sha256Hex([legacyCore.record_hash, '', legacyCore.issuer, legacyCore.timestamp].join('|')),
  signature_algorithm: 'sha256_chain_legacy',
  verification_status: 'issued'
};

const pick = (r) => ({
  receipt_id: r.receipt_id,
  record_hash: r.record_hash,
  previous_hash: r.previous_hash,
  receipt_hash: r.receipt_hash,
  issuer: r.issuer,
  signature: r.signature,
  signature_algorithm: r.signature_algorithm,
  verification_status: r.verification_status
});

const receipt = [
  { id: 'receipt-signed-genesis', signer_seed_hex: signerSeed, record: receiptRecord, previous_hash: null, timestamp: first.timestamp, expected: pick(first) },
  { id: 'receipt-signed-chained', signer_seed_hex: signerSeed, record: { ...receiptRecord, status: 'active' }, previous_hash: first.receipt_hash, timestamp: second.timestamp, expected: pick(second) },
  { id: 'receipt-unsigned', issuer: 'iricity-state-stack', record: receiptRecord, previous_hash: null, timestamp: unsigned.timestamp, expected: pick(unsigned) },
  { id: 'receipt-legacy-chain-digest', legacy: true, record: receiptRecord, receipt: legacy, expected: { verified: true } }
];

// Objects a verifier must reject. Each is a well-formed-looking variation of a valid object.
const otherDid = keyPairFromSeed(otherSeed).did;
const rejections = [
  { id: 'envelope-payload-tampered', kind: 'envelope', object: { ...envelopeFirst, payload: { ...ommPayload, NORAD_CAT_ID: 1 } } },
  { id: 'envelope-signer-swapped', kind: 'envelope', object: { ...envelopeFirst, signer: otherDid, signature: { ...envelopeFirst.signature, key_id: otherDid } } },
  { id: 'envelope-signature-corrupted', kind: 'envelope', object: { ...envelopeFirst, signature: { ...envelopeFirst.signature, value: `${envelopeFirst.signature.value.slice(0, -2)}AA` } } },
  { id: 'envelope-key-id-mismatch', kind: 'envelope', object: { ...envelopeFirst, signature: { ...envelopeFirst.signature, key_id: otherDid } } },
  { id: 'envelope-hash-altered', kind: 'envelope', object: { ...envelopeFirst, envelope_hash: `sha256:${'0'.repeat(64)}` } },
  { id: 'envelope-id-altered', kind: 'envelope', object: { ...envelopeFirst, envelope_id: `env_${'0'.repeat(24)}` } },
  { id: 'envelope-version-unknown', kind: 'envelope', object: { ...envelopeFirst, envelope_version: 'state-envelope/9' } },
  { id: 'envelope-previous-link-altered', kind: 'envelope', object: { ...envelopeChained, previous_envelope_hash: envelopeDetached.envelope_hash } },
  { id: 'envelope-signature-missing', kind: 'envelope', object: Object.fromEntries(Object.entries(envelopeFirst).filter(([k]) => k !== 'signature')) },
  { id: 'envelope-signature-padded-encoding', kind: 'envelope', object: { ...envelopeFirst, signature: { ...envelopeFirst.signature, value: `${envelopeFirst.signature.value}==` } } },
  { id: 'envelope-created-at-not-utc', kind: 'envelope', object: { ...envelopeFirst, created_at: '2026-01-01T00:00:00+05:30' } },
  { id: 'envelope-expected-signer-other', kind: 'envelope', object: envelopeFirst, options: { expected_signer: otherDid } },
  { id: 'envelope-payload-type-not-allowed', kind: 'envelope', object: envelopeFirst, options: { allowed_payload_types: ['opaque.json/1'] } },
  { id: 'envelope-detached-wrong-payload', kind: 'envelope', object: envelopeDetached, options: { payload: 'a different string' } },
  { id: 'receipt-record-hash-tampered', kind: 'receipt', object: { ...first, record_hash: hashRecord({ ...receiptRecord, entity_id: 'NODE-2' }) } },
  { id: 'receipt-issuer-swapped', kind: 'receipt', object: { ...first, issuer: otherDid, key_id: otherDid } },
  { id: 'receipt-signature-corrupted', kind: 'receipt', object: { ...first, signature: `${first.signature.slice(0, -2)}AA` } },
  { id: 'receipt-signature-stripped', kind: 'receipt', object: { ...first, signature: null, signature_algorithm: 'none', key_id: null, verification_status: 'unsigned' } },
  { id: 'receipt-id-altered', kind: 'receipt', object: { ...first, receipt_id: `rcp_${'0'.repeat(24)}` } },
  { id: 'receipt-hash-altered', kind: 'receipt', object: { ...first, receipt_hash: `sha256:${'0'.repeat(64)}` } },
  { id: 'receipt-version-unknown', kind: 'receipt', object: { ...first, receipt_version: 'state-receipt/9' } },
  { id: 'receipt-previous-link-broken', kind: 'receipt', object: second, options: { previous_receipt: unsigned } },
  { id: 'receipt-wrong-record', kind: 'receipt', object: first, options: { record: { ...receiptRecord, entity_id: 'NODE-2' } } },
  { id: 'receipt-expected-issuer-other', kind: 'receipt', object: first, options: { expected_issuer: otherDid } },
  { id: 'receipt-unsigned-claims-issued', kind: 'receipt', object: { ...unsigned, verification_status: 'issued' } },
  { id: 'receipt-unsigned-did-issuer', kind: 'receipt', object: { ...unsigned, issuer: signer.did } }
];

const vectors = {
  vectors_version: VECTORS_VERSION,
  generated_at: '2026-10-17T00:00:00.000Z',
  notes: [
    'canonical_json follows RFC 8785 for all JSON values; inputs are stored with their original key order so unsorted serializers fail.',
    'hash_payload references always cover canonical JSON: a string payload is hashed as the JSON string, never as raw text.',
    'ed25519 vectors are RFC 8032 section 7.1 tests 1 and 2.',
    'did_key framing is multicodec ed25519-pub (0xed 0x01) + base58btc with multibase prefix z; both directions are checked.',
    'envelope and receipt signatures are deterministic: an independent implementation must reproduce them byte for byte.',
    'rejections are objects a conforming verifier must report as verified=false.',
    'An implementation conforms only when every suite passes and none is skipped.'
  ],
  canonical_json,
  hash_payload,
  base58btc,
  did_key,
  ed25519,
  envelope,
  receipt,
  rejections
};

const outPath = path.join(here, 'vectors.json');
const serialized = `${JSON.stringify(vectors, null, 2)}\n`;
fs.writeFileSync(outPath, serialized);

const lockPath = path.join(here, 'vectors.lock.json');
const lock = {
  vectors_version: VECTORS_VERSION,
  sha256: createHash('sha256').update(serialized).digest('hex'),
  note: 'SHA-256 of conformance/vectors.json with LF line endings. Immutable for this vectors_version; a change to the vectors is a new version, never an edit.'
};
fs.writeFileSync(lockPath, `${JSON.stringify(lock, null, 2)}\n`);
const count = Object.entries(vectors)
  .filter(([key, value]) => key !== 'notes' && Array.isArray(value))
  .reduce((sum, [, list]) => sum + list.length, 0);
process.stdout.write(`wrote ${outPath} (${count} vectors, version ${VECTORS_VERSION}) and ${lockPath} (sha256 ${lock.sha256.slice(0, 16)})\n`);
